#include <bits/stdc++.h>
using namespace std;
#define ll long long

    ll n;
    vector<ll> a;
    vector<ll> pref_sum;
    
    
ll rsum(ll l, ll r){
    if(r<l) return 0;
    return pref_sum[r] - pref_sum[l-1];
}

ll get_y(ll x){
    ll l = 1, r = n - x;
    ll ans = 0;
    while(l<=r){
        ll mid = (l+r)/2;
        ll next_t_sum = a[x+2*mid-1] + a[x+2*mid];
        ll last = a[3*n - 2*x - mid+1];
        // cout << 3*n - 2*x - mid << " "<<mid << " " << next_t_sum << " " << last <<" "<< l << " "<<r<<endl;;
        if(next_t_sum >= 3*last){
            // cout << "yes"<<endl;
            ans = mid;
            l = mid+1;
        }
        else{
            r = mid-1;
        }
    }
    return ans;
}
    
    
void solve(){
    cin >>n;
    a.clear();
    pref_sum.clear();
    pref_sum.resize(3*n+1);
    a.resize(3*n+1);
    for(int i=1;i<=3*n;i++){
        cin >>a[i];
    }
    sort(a.begin()+1,a.end());
    reverse(a.begin()+1,a.end());
    // for(int i=1;i<=3*n;i++){
    //     cout << a[i]<<" ";
    // }
    // cout << endl;
    for(int i=1;i<=3*n;i++){
        pref_sum[i] = pref_sum[i-1] + a[i];
    }
    ll ans = 0;
    ans = 3* rsum(1,3*n);
    for(int x = 0;x<=n;x++){
        ll tmp = 6*rsum(1,x);
        ll y = get_y(x);
        // cout << "x = "<<x<<" y = "<<y<<endl;
        tmp = 6*rsum(1,x) + 4*rsum(x+1,x+ 2*y) + 3*rsum(x+2*y+1,3*n -2*x - y);
        ans = max(ans,tmp);
    }
    cout << ans << endl;
    
}

int main() {
	// your code goes here
	ll test;
	cin >>test;
	while(test--){
	    solve();
	}

}
